<script setup lang="ts">
import { onBeforeUnmount, onMounted, watch } from 'vue'
import AdminLayout from '@/layouts/AdminLayout.vue'
import AssessmentTable from '@/components/admin/AssessmentTable.vue'
import { useAssessmentStore } from '@/stores/assessments'
import type { ReviewStatus, SceneFilter } from '@/types/assessment'
const scenes: {value:SceneFilter;label:string}[]=[{value:'all',label:'全部'},{value:'aviation',label:'航空'},{value:'community',label:'社区'}]
const store=useAssessmentStore();onMounted(()=>store.load())
let searchTimer: ReturnType<typeof setTimeout> | undefined
watch(() => store.search, () => { clearTimeout(searchTimer); searchTimer = setTimeout(() => { void store.load() }, 300) })
onBeforeUnmount(() => clearTimeout(searchTimer))
async function setStatus(payload:{id:string;status:ReviewStatus}){try{await store.setReviewStatus(payload.id,payload.status)}catch{await store.load()}}
</script>
<template><AdminLayout><header class="page-header"><div><div class="eyebrow">ASSESSMENT REPORTS</div><h1>测评报告</h1><p>统一查看航空与社区测评结果。</p></div><button class="secondary-button" :disabled="store.loading" @click="store.load">刷新数据</button></header><section class="toolbar"><div class="scene-filter" role="group" aria-label="测评场景"><button v-for="item in scenes" :key="item.value" type="button" :aria-pressed="store.scene===item.value" :class="{active:store.scene===item.value}" @click="store.setScene(item.value)">{{ item.label }}</button></div><div class="search-box"><span>⌕</span><input v-model="store.search" placeholder="搜索姓名、工号或报告编号"></div></section><div v-if="store.error" class="alert alert--error">{{ store.error }}</div><div v-if="!store.loading&&!store.error" class="record-summary" aria-live="polite"><span>{{ store.search.trim() ? '搜索结果' : scenes.find(item=>item.value===store.scene)?.label }} · 共 <strong>{{ store.total }}</strong> 份</span><span>已加载 {{ store.records.length }} 份<span v-if="store.filtered.length!==store.records.length"> · 当前筛选显示 {{ store.filtered.length }} 份</span></span></div><AssessmentTable :records="store.filtered" :loading="store.loading" @status="setStatus"/><div v-if="store.hasMore&&!store.loading" class="load-more"><button class="secondary-button" :disabled="store.loadingMore" @click="store.loadMore">{{ store.loadingMore?'正在加载…':`加载更多（已加载 ${store.records.length} / ${store.total} 份）` }}</button></div></AdminLayout></template>
<style scoped>.record-summary{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;margin:0 0 14px;color:#617384;font-size:14px}.record-summary strong{color:#24644e;font-size:17px}.toolbar{flex-wrap:wrap;gap:16px}.scene-filter{display:flex;gap:4px;padding:4px;background:#eef3f1;border-radius:12px}.scene-filter button{min-width:76px;min-height:40px;border:0;border-radius:9px;background:transparent;color:#4d635b;font-size:15px;cursor:pointer}.scene-filter button.active{background:#fff;color:#24644e;font-weight:700;box-shadow:0 2px 8px #20392d12}.search-box{flex:1;min-width:220px}.load-more{display:flex;justify-content:center;padding:18px 0 6px}</style>
